export const FULFILMENT_FLOW = ["placed", "paid", "packed", "shipped", "delivered"] as const;

export type FulfilmentState = (typeof FULFILMENT_FLOW)[number];
export type OrderState = FulfilmentState | "cancelled";

const CANCELLABLE: readonly OrderState[] = ["placed", "paid", "packed"];

export function isOrderState(value: string): value is OrderState {
  return value === "cancelled" || (FULFILMENT_FLOW as readonly string[]).includes(value);
}

export function nextState(state: OrderState): FulfilmentState | undefined {
  if (state === "cancelled") return undefined;
  return FULFILMENT_FLOW[FULFILMENT_FLOW.indexOf(state) + 1];
}

export function isCancellable(state: OrderState): boolean {
  return CANCELLABLE.includes(state);
}

