import { DomainError } from "./domain-error";
import { OrderLine } from "./order-line";
import { OrderState, isCancellable, nextState } from "./order-state";

export class Order {
  readonly id: string;
  readonly lines: readonly OrderLine[];
  private currentState: OrderState;

  constructor(id: string, lines: readonly OrderLine[]) {
    if (lines.length === 0) {
      throw new DomainError("validation", "An order needs at least one line");
    }
    this.id = id;
    this.lines = lines;
    this.currentState = "placed";
  }

  get state(): OrderState {
    return this.currentState;
  }

  advanceTo(target: OrderState): void {
    if (nextState(this.currentState) !== target) {
      throw new DomainError(
        "invalid_transition",
        `Cannot move order ${this.id} from ${this.currentState} to ${target}`,
      );
    }
    this.currentState = target;
  }

  cancel(): void {
    if (!isCancellable(this.currentState)) {
      throw new DomainError(
        "invalid_transition",
        `Order ${this.id} cannot be cancelled once ${this.currentState}`,
      );
    }
    this.currentState = "cancelled";
  }
}

