import { DomainError } from "./domain-error";

export class Product {
  readonly id: string;
  readonly name: string;
  private readonly onHand: number;
  private reserved: number;

  constructor(id: string, name: string, onHand: number) {
    if (!Number.isInteger(onHand) || onHand < 0) {
      throw new DomainError("validation", "Stock must be a non-negative integer");
    }
    this.id = id;
    this.name = name;
    this.onHand = onHand;
    this.reserved = 0;
  }

  get available(): number {
    return this.onHand - this.reserved;
  }

  get reservedQuantity(): number {
    return this.reserved;
  }

  get onHandQuantity(): number {
    return this.onHand;
  }

  canReserve(quantity: number): boolean {
    return quantity <= this.available;
  }

  reserve(quantity: number): void {
    if (!this.canReserve(quantity)) {
      throw new DomainError(
        "insufficient_stock",
        `Insufficient stock for product ${this.id}: requested ${quantity}, available ${this.available}`,
      );
    }
    this.reserved += quantity;
  }

  release(quantity: number): void {
    this.reserved = Math.max(0, this.reserved - quantity);
  }
}

