import { DomainError } from "./domain-error";
import { OrderLine } from "./order-line";
import { Product } from "./product";

export function totalsByProduct(lines: readonly OrderLine[]): Map<string, number> {
  const totals = new Map<string, number>();
  for (const line of lines) {
    totals.set(line.productId, (totals.get(line.productId) ?? 0) + line.quantity);
  }
  return totals;
}

function productFor(products: ReadonlyMap<string, Product>, productId: string): Product {
  const product = products.get(productId);
  if (!product) {
    throw new DomainError("not_found", `Product ${productId} not found`);
  }
  return product;
}

/** Reserves every line or none: all lines are checked before any stock moves. */
export function reserveStock(products: ReadonlyMap<string, Product>, lines: readonly OrderLine[]): void {
  const totals = totalsByProduct(lines);
  for (const [productId, quantity] of totals) {
    const product = productFor(products, productId);
    if (!product.canReserve(quantity)) {
      throw new DomainError(
        "insufficient_stock",
        `Insufficient stock for product ${productId}: requested ${quantity}, available ${product.available}`,
      );
    }
  }
  for (const [productId, quantity] of totals) {
    productFor(products, productId).reserve(quantity);
  }
}

export function releaseStock(products: ReadonlyMap<string, Product>, lines: readonly OrderLine[]): void {
  for (const [productId, quantity] of totalsByProduct(lines)) {
    products.get(productId)?.release(quantity);
  }
}

